/**
 * Content moderation for user-submitted text.
 *
 * Scope and honest limitations:
 *   - This is a pattern-based filter. It catches obvious abuse — slurs, explicit
 *     sexual content, threats of violence, and spam — and it will miss cleverly
 *     obfuscated material. It is a first line of defence, NOT a guarantee.
 *   - It is deliberately tuned to avoid false positives on legitimate technical
 *     writing. Cloud architecture discussion is full of words that naive filters
 *     flag: "kill the process", "abort the deployment", "master node",
 *     "execute the job", "terminate the instance", "attack surface". Those must
 *     never be blocked, so matching is done on specific abusive phrasings rather
 *     than on individual alarming-sounding words.
 *   - Any real service also needs user reporting and human review. A filter
 *     alone is not a moderation strategy.
 *
 * Returns { ok: true } or { ok: false, reason } — callers should reject with a
 * 400 and show the reason to the user.
 */

// Normalises common evasion: unicode lookalikes, repeated characters, and
// symbol substitution (h3ll0, f*ck, s.h.i.t).
function normalise(input) {
  let s = String(input || "").toLowerCase();
  s = s.normalize("NFKD").replace(/[\u0300-\u036f]/g, "");
  const SUBS = { "0": "o", "1": "i", "3": "e", "4": "a", "5": "s", "7": "t", "@": "a", "$": "s", "!": "i" };
  s = s.replace(/[013457@$!]/g, (c) => SUBS[c] || c);
  s = s.replace(/[^a-z0-9\s]/g, " ");   // strip punctuation used to break words
  s = s.replace(/(.)\1{2,}/g, "$1$1");  // collapse looooong runs
  s = s.replace(/\s+/g, " ").trim();
  return s;
}

// Collapsed form with all whitespace removed, to catch "f u c k" style spacing.
function collapse(s) {
  return s.replace(/\s+/g, "");
}

// Severe slurs and explicit sexual content. Kept as fragments matched against
// the collapsed string so spacing tricks don't evade them.
const SLURS = [
  "nigger", "nigga", "faggot", "kike", "chink", "spic", "tranny", "retard",
  "wetback", "beaner", "coon", "raghead", "gook",
];

const SEXUAL_EXPLICIT = [
  "childporn", "cp0rn", "loli", "pedo", "rapevideo", "underagesex", "minorsex",
];

// Threats and incitement. Phrase-based, because the individual words are all
// ordinary in a technical context.
const VIOLENCE_PATTERNS = [
  /\bi (?:will|am going to|gonna) (?:kill|murder|shoot|stab|hurt) (?:you|him|her|them|u)\b/,
  /\b(?:kill|murder|shoot|stab) (?:yourself|urself)\b/,
  /\bkys\b/,
  /\bgo (?:kill|hang) yourself\b/,
  /\b(?:how to (?:make|build)) (?:a )?(?:bomb|pipe bomb|explosive)\b/,
  /\b(?:school|mass) shooting\b.*\b(?:plan|going to|will)\b/,
  /\bi hope you die\b/,
  /\b(?:death|rape) threat\b.*\b(?:against|to) (?:you|him|her)\b/,
];

const HARASSMENT_PATTERNS = [
  /\byou(?:re| are) (?:a )?(?:worthless|pathetic) (?:piece of )?(?:shit|garbage|trash)\b/,
  /\bnobody (?:loves|wants) you\b.*\bdie\b/,
];

// Spam heuristics — these protect the feed from becoming a link farm.
const SPAM_PATTERNS = [
  /\b(?:buy|cheap|discount|free)\b.*\b(?:viagra|cialis|casino|crypto giveaway|forex)\b/,
  /\bclick here to (?:claim|win|earn)\b/,
  /\b(?:telegram|whatsapp)\b.*\b(?:investment|profit|signals)\b/,
];

function countLinks(raw) {
  const m = String(raw || "").match(/https?:\/\/|www\./gi);
  return m ? m.length : 0;
}

/**
 * @param {string} text  the user-submitted text
 * @param {object} [opts]
 * @param {number} [opts.maxLinks]  reject beyond this many URLs (default 3)
 * @param {boolean} [opts.allowLinks]  set false to reject any URL
 */
function checkText(text, opts = {}) {
  const raw = String(text || "");
  if (!raw.trim()) return { ok: true };

  const norm = normalise(raw);
  const flat = collapse(norm);

  for (const term of SLURS) {
    if (flat.includes(term)) {
      return { ok: false, reason: "This contains language we don't allow. Please revise it." };
    }
  }

  for (const term of SEXUAL_EXPLICIT) {
    if (flat.includes(term)) {
      return { ok: false, reason: "This content isn't allowed." };
    }
  }

  for (const re of VIOLENCE_PATTERNS) {
    if (re.test(norm)) {
      return { ok: false, reason: "This appears to contain a threat of violence, which isn't allowed." };
    }
  }

  for (const re of HARASSMENT_PATTERNS) {
    if (re.test(norm)) {
      return { ok: false, reason: "This appears to be harassment, which isn't allowed." };
    }
  }

  for (const re of SPAM_PATTERNS) {
    if (re.test(norm)) {
      return { ok: false, reason: "This looks like spam." };
    }
  }

  const maxLinks = opts.maxLinks === undefined ? 3 : opts.maxLinks;
  const links = countLinks(raw);
  if (opts.allowLinks === false && links > 0) {
    return { ok: false, reason: "Links aren't allowed here." };
  }
  if (links > maxLinks) {
    return { ok: false, reason: `Please include no more than ${maxLinks} links.` };
  }

  // Wall-of-caps shouting, only for longer text so acronyms like VPC/EC2/IAM
  // and short exclamations are unaffected.
  const letters = raw.replace(/[^a-zA-Z]/g, "");
  if (letters.length > 40) {
    const caps = raw.replace(/[^A-Z]/g, "").length;
    if (caps / letters.length > 0.8) {
      return { ok: false, reason: "Please don't post in all capitals." };
    }
  }

  return { ok: true };
}

module.exports = { checkText, normalise };
